content:
{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Subject or subject’s legally acceptable representative has provided informed consent prior to initiation of any study specific activities/procedures.",
      "quote": "Subject or subject’s legally acceptable representative has provided informed consent prior to initiation of any study specific activities/procedures."
    },
    {
      "kind": "inclusion",
      "text": "Age ≥ 18 years of age",
      "quote": "Age ≥ 18 years of age",
      "thresholds": [
        {
          "test": "Age",
          "op": ">=",
          "value": 18,
          "unit": "years"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Histologically or pathologically documented, locally-advanced and unresectable or metastatic NSCLC.",
      "quote": "Histologically or pathologically documented, locally-advanced and unresectable or metastatic NSCLC."
    },
    {
      "kind": "inclusion",
      "text": "Have documentation of KRAS p.G12C mutation confirmed by central testing through the current protocol or have documentation of KRAS p.G12C mutation through Amgen Study 20190294 prior to enrollment.",
      "quote": "Have documentation of KRAS p.G12C mutation confirmed by central testing through the current protocol or have documentation of KRAS p.G12C mutation through Amgen Study 20190294 prior to enrollment."
    },
    {
      "kind": "inclusion",
      "text": "Subjects will have received and progressed or experienced disease recurrence on or after receiving at least 1 prior systemic therapy for locally advanced and unresectable or metastatic disease. Prior treatment must include a platinum-based doublet chemotherapy and checkpoint inhibitor for advanced or metastatic disease, either given as one line of therapy or as individual lines of therapy unless the subject has a medical contraindication to one of the required therapies. If the subject has a medical contraindication to a required therapy, the subject may be enrolled only after the investigator discusses and obtains approval from the Amgen medical monitor.",
      "quote": "Subjects will have received and progressed or experienced disease recurrence on or after receiving at least 1 prior systemic therapy for locally advanced and unresectable or metastatic disease. Prior treatment must include a platinum-based doublet chemotherapy and checkpoint inhibitor for advanced or metastatic disease, either given as one line of therapy or as individual lines of therapy unless the subject has a medical contraindication to one of the required therapies. If the subject has a medical contraindication to a required therapy, the subject may be enrolled only after the investigator discusses and obtains approval from the Amgen medical monitor."
    },
    {
      "kind": "inclusion",
      "text": "Adjuvant therapy will count as a line of therapy if the subject progressed on or within 6 months of adjuvant therapy administration.",
      "quote": "Adjuvant therapy will count as a line of therapy if the subject progressed on or within 6 months of adjuvant therapy administration."
    },
    {
      "kind": "inclusion",
      "text": "In locally advanced and unresectable NSCLC, disease progression on or within 6 months of end of prior curatively intended multimodal therapy will count as a line of therapy. If chemoradiation is followed by planned systemic therapy without documented progression between chemoradiation and systemic therapy, the entire treatment course counts as one line of therapy.",
      "quote": "In locally advanced and unresectable NSCLC, disease progression on or within 6 months of end of prior curatively intended multimodal therapy will count as a line of therapy. If chemoradiation is followed by planned systemic therapy without documented progression between chemoradiation and systemic therapy, the entire treatment course counts as one line of therapy."
    },
    {
      "kind": "inclusion",
      "text": "Maintenance therapy following platinum doublet-based chemotherapy is not considered as a separate line of therapy.",
      "quote": "Maintenance therapy following platinum doublet-based chemotherapy is not considered as a separate line of therapy."
    },
    {
      "kind": "inclusion",
      "text": "Subjects must have archived tumor tissue samples (formalin fixed, paraffin embedded [FFPE] sample [FFPE of excisional, core needle, or fine needle aspirate] collected within 5 years) or be willing to undergo pre-treatment tumor biopsy (excisional, core needle, or fine needle aspirate) for tissue prior to enrollment.",
      "quote": "Subjects must have archived tumor tissue samples (formalin fixed, paraffin embedded [FFPE] sample [FFPE of excisional, core needle, or fine needle aspirate] collected within 5 years) or be willing to undergo pre-treatment tumor biopsy (excisional, core needle, or fine needle aspirate) for tissue prior to enrollment."
    },
    {
      "kind": "inclusion",
      "text": "Measurable disease per RECIST v1.1 criteria. Lesions previously radiated are not considered measurable unless they have progressed after radiation.",
      "quote": "Measurable disease per RECIST v1.1 criteria. Lesions previously radiated are not considered measurable unless they have progressed after radiation."
    },
    {
      "kind": "inclusion",
      "text": "ECOG Performance Status of ≤ 1",
      "quote": "ECOG Performance Status of ≤ 1",
      "thresholds": [
        {
          "test": "ECOG Performance Status",
          "op": "<=",
          "value": 1
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Adequate hematologic laboratory assessments, defined as the following within 10 days prior to start of study therapy: a) Absolute neutrophil count (ANC) ≥ 1500 cells/µl (without granulocyte colony-stimulating factor support within 10 days of laboratory test used to determine eligibility) b) Hemoglobin ≥ 9.0 g/dL (without transfusion within 2 weeks of laboratory test used to determine eligibility) c) Platelet count ≥ 100000/µl (without transfusion within 2 weeks of laboratory test used to determine eligibility)",
      "quote": "Adequate hematologic laboratory assessments, defined as the following within 10 days prior to start of study therapy: a) Absolute neutrophil count (ANC) ≥ 1500 cells/µl (without granulocyte colony-stimulating factor support within 10 days of laboratory test used to determine eligibility) b) Hemoglobin ≥ 9.0 g/dL (without transfusion within 2 weeks of laboratory test used to determine eligibility) c) Platelet count ≥ 100000/µl (without transfusion within 2 weeks of laboratory test used to determine eligibility)",
      "thresholds": [
        {
          "test": "ANC",
          "op": ">=",
          "value": 1500,
          "unit": "cells/µl"
        },
        {
          "test": "Hemoglobin",
          "op": ">=",
          "value": 9.0,
          "unit": "g/dL"
        },
        {
          "test": "Platelet count",
          "op": ">=",
          "value": 100000,
          "unit": "/µl"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Life expectancy of > 3 months, in the opinion of the investigator",
      "quote": "Life expectancy of > 3 months, in the opinion of the investigator"
    },
    {
      "kind": "inclusion",
      "text": "Adequate liver function, defined as the following: a) Aspartate aminotransferase (AST) and, alanine aminotransferase (ALT) ≤ 2.5 times the upper limit of normal (ULN), except if alkaline phosphatase > 2.5 times the ULN, then AST and/or ALT must be ≤ 1.5 times the ULN b) Serum bilirubin ≤ 1.0 x ULN",
      "quote": "Adequate liver function, defined as the following: a) Aspartate aminotransferase (AST) and, alanine aminotransferase (ALT) ≤ 2.5 times the upper limit of normal (ULN), except if alkaline phosphatase > 2.5 times the ULN, then AST and/or ALT must be ≤ 1.5 times the ULN b) Serum bilirubin ≤ 1.0 x ULN",
      "thresholds": [
        {
          "test": "AST",
          "op": "<=",
          "value": 2.5,
          "unit": "x ULN"
        },
        {
          "test": "ALT",
          "op": "<=",
          "value": 2.5,
          "unit": "x ULN"
        },
        {
          "test": "AST/ALT (if ALP > 2.5x ULN)",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "Serum bilirubin",
          "op": "<=",
          "value": 1.0,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "International normalized ratio (INR) and activated partial thromboplastin time ≤ 1.5 x ULN",
      "quote": "International normalized ratio (INR) and activated partial thromboplastin time ≤ 1.5 x ULN",
      "thresholds": [
        {
          "test": "INR",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "aPTT",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Serum creatinine ≤ 1.5 x ULN OR creatinine clearance ≥ 60 mL/min. Cockcroft-Gault formula will be used for creatinine clearance calculation. Twenty-four hour urine collection is not required but is allowed.",
      "quote": "Serum creatinine ≤ 1.5 x ULN OR creatinine clearance ≥ 60 mL/min. Cockcroft-Gault formula will be used for creatinine clearance calculation. Twenty-four hour urine collection is not required but is allowed.",
      "thresholds": [
        {
          "test": "Serum creatinine",
          "op": "<=",
          "value": 1.5,
          "unit": "x ULN"
        },
        {
          "test": "Creatinine clearance",
          "op": ">=",
          "value": 60,
          "unit": "mL/min"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "QTc ≤ 470 msec in females and ≤ 450 msec in males (based on average of screening triplicates)",
      "quote": "QTc ≤ 470 msec in females and ≤ 450 msec in males (based on average of screening triplicates)",
      "thresholds": [
        {
          "test": "QTc (female)",
          "op": "<=",
          "value": 470,
          "unit": "msec"
        },
        {
          "test": "QTc (male)",
          "op": "<=",
          "value": 450,
          "unit": "msec"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Ability to take oral medications and willing to record daily adherence to investigational product",
      "quote": "Ability to take oral medications and willing to record daily adherence to investigational product"
    },
    {
      "kind": "exclusion",
      "text": "Subjects have received prior docetaxel in unresectable or metastatic setting (including subjects who received prior docetaxel in first line for metastatic disease, but not including subjects who received prior docetaxel neoadjuvantly or adjuvantly and did not progress within 6 months of end of therapy).",
      "quote": "Subjects have received prior docetaxel in unresectable or metastatic setting (including subjects who received prior docetaxel in first line for metastatic disease, but not including subjects who received prior docetaxel neoadjuvantly or adjuvantly and did not progress within 6 months of end of therapy)."
    },
    {
      "kind": "exclusion",
      "text": "Mixed small-cell lung cancer or mixed NSCLC histology",
      "quote": "Mixed small-cell lung cancer or mixed NSCLC histology"
    },
    {
      "kind": "exclusion",
      "text": "Previously identified driver mutation (according to local standard of care or guidelines) other than KRAS p.G12C for which an approved therapy is available (including EGFR, ALK, etc).",
      "quote": "Previously identified driver mutation (according to local standard of care or guidelines) other than KRAS p.G12C for which an approved therapy is available (including EGFR, ALK, etc)."
    },
    {
      "kind": "exclusion",
      "text": "Active brain metastases. Subjects who have had brain metastases resected or have received whole brain radiation therapy ending at least 4 weeks (or stereotactic radiosurgery ending at least 2 weeks) prior to study day 1 are eligible if they meet all of the following criteria: a) residual neurological symptoms grade ≤ 2; b) on stable doses of dexamethasone or equivalent for at least 2 weeks, if applicable; and c) follow-up MRI performed within 30 days prior to enrollment shows no progression or new lesions appearing. Active brain metastases are defined as: Untreated brain lesions (new or progressing) and/or symptomatic brain lesions (symptoms as determined by the investigator), present at the time of study entry.",
      "quote": "Active brain metastases. Subjects who have had brain metastases resected or have received whole brain radiation therapy ending at least 4 weeks (or stereotactic radiosurgery ending at least 2 weeks) prior to study day 1 are eligible if they meet all of the following criteria: a) residual neurological symptoms grade ≤ 2; b) on stable doses of dexamethasone or equivalent for at least 2 weeks, if applicable; and c) follow-up MRI performed within 30 days prior to enrollment shows no progression or new lesions appearing. Active brain metastases are defined as: Untreated brain lesions (new or progressing) and/or symptomatic brain lesions (symptoms as determined by the investigator), present at the time of study entry."
    },
    {
      "kind": "exclusion",
      "text": "Leptomeningeal disease.",
      "quote": "Leptomeningeal disease."
    },
    {
      "kind": "exclusion",
      "text": "Uncontrolled pleural effusion, pericardial effusion, or ascites requiring recurrent drainage procedures at a frequency greater than monthly. Subjects with PleurX catheters in place may be considered for the study with Medical Monitor approval.",
      "quote": "Uncontrolled pleural effusion, pericardial effusion, or ascites requiring recurrent drainage procedures at a frequency greater than monthly. Subjects with PleurX catheters in place may be considered for the study with Medical Monitor approval."
    },
    {
      "kind": "exclusion",
      "text": "Known history of Human Immunodeficiency Virus (HIV) infection",
      "quote": "Known history of Human Immunodeficiency Virus (HIV) infection"
    },
    {
      "kind": "exclusion",
      "text": "Exclusion of hepatitis infection based on the following results and/or criteria: a) Positive hepatitis B surface antigen (HepBsAg) (indicative of chronic Hepatitis B or recent acute hepatitis B) b) Negative HepBsAg with a positive for hepatitis B core antibody (Hepatitis B core antibody testing is not required for screening, however if this is done and is positive, then hepatitis B surface antibody [Anti-HBs] testing is necessary. Undetectable anti-HBs in this setting would suggest unclear and possible infection, and needs exclusion). c) Positive Hepatitis C virus antibody: Hepatitis C virus RNA by polymerase chain reaction is necessary. Detectable Hepatitis C virus RNA renders the subject ineligible. If above antibody/antigen testing is not able to be obtained, positive hepatitis B or C viral load",
      "quote": "Exclusion of hepatitis infection based on the following results and/or criteria: a) Positive hepatitis B surface antigen (HepBsAg) (indicative of chronic Hepatitis B or recent acute hepatitis B) b) Negative HepBsAg with a positive for hepatitis B core antibody (Hepatitis B core antibody testing is not required for screening, however if this is done and is positive, then hepatitis B surface antibody [Anti-HBs] testing is necessary. Undetectable anti-HBs in this setting would suggest unclear and possible infection, and needs exclusion). c) Positive Hepatitis C virus antibody: Hepatitis C virus RNA by polymerase chain reaction is necessary. Detectable Hepatitis C virus RNA renders the subject ineligible. If above antibody/antigen testing is not able to be obtained, positive hepatitis B or C viral load"
    },
    {
      "kind": "exclusion",
      "text": "Malignancy other than NSCLC within 3 years prior to randomization, with the exception of those with a negligible risk of metastases or death and treated with expected curative outcome (such as adequately treated carcinoma in situ of the cervix, basal cell carcinoma, cutaneous squamous cell carcinoma, localized prostate cancer treated with curative intent, or ductal carcinoma in situ treated surgically with curative intent).",
      "quote": "Malignancy other than NSCLC within 3 years prior to randomization, with the exception of those with a negligible risk of metastases or death and treated with expected curative outcome (such as adequately treated carcinoma in situ of the cervix, basal cell carcinoma, cutaneous squamous cell carcinoma, localized prostate cancer treated with curative intent, or ductal carcinoma in situ treated surgically with curative intent)."
    },
    {
      "kind": "exclusion",
      "text": "Major surgery within 28 days of study day 1",
      "quote": "Major surgery within 28 days of study day 1"
    },
    {
      "kind": "exclusion",
      "text": "Significant gastrointestinal disorder that results in significant malabsorption, requirement for intravenous alimentation, or inability to take oral medication.",
      "quote": "Significant gastrointestinal disorder that results in significant malabsorption, requirement for intravenous alimentation, or inability to take oral medication."
    },
    {
      "kind": "exclusion",
      "text": "Significant cardiovascular disease, such as New York Heart Association cardiac disease (Class II or greater), myocardial infarction within 6 months prior to study day 1, unstable arrhythmias or unstable angina.",
      "quote": "Significant cardiovascular disease, such as New York Heart Association cardiac disease (Class II or greater), myocardial infarction within 6 months prior to study day 1, unstable arrhythmias or unstable angina."
    },
    {
      "kind": "exclusion",
      "text": "Severe infections within 4 weeks prior to randomization including, but not limited to hospitalization for complications of infection, bacteremia or severe pneumonia.",
      "quote": "Severe infections within 4 weeks prior to randomization including, but not limited to hospitalization for complications of infection, bacteremia or severe pneumonia."
    },
    {
      "kind": "exclusion",
      "text": "Therapeutic oral or intravenous antibiotics within 2 weeks prior to randomization. Prophylactic antibiotics are allowed with Amgen medical monitor approval.",
      "quote": "Therapeutic oral or intravenous antibiotics within 2 weeks prior to randomization. Prophylactic antibiotics are allowed with Amgen medical monitor approval."
    },
    {
      "kind": "exclusion",
      "text": "Current CTCAE version 5.0 grade ≥ 2 peripheral neuropathy",
      "quote": "Current CTCAE version 5.0 grade ≥ 2 peripheral neuropathy"
    },
    {
      "kind": "exclusion",
      "text": "Unresolved toxicities from prior anti-tumor therapy, defined as not having resolved to CTCAE version 5.0 grade 0 or 1, or to levels dictated in the eligibility criteria with the exception of alopecia (any grade allowed) or toxicities from prior anti-tumor therapy that are considered irreversible (defined as having been present and stable for > 6 months), endocrine adverse events that are stably maintained on appropriate replacement therapy.",
      "quote": "Unresolved toxicities from prior anti-tumor therapy, defined as not having resolved to CTCAE version 5.0 grade 0 or 1, or to levels dictated in the eligibility criteria with the exception of alopecia (any grade allowed) or toxicities from prior anti-tumor therapy that are considered irreversible (defined as having been present and stable for > 6 months), endocrine adverse events that are stably maintained on appropriate replacement therapy."
    },
    {
      "kind": "exclusion",
      "text": "Anti-tumor therapy (chemotherapy, antibody therapy, molecular targeted therapy, retinoid therapy, hormonal therapy [except for subjects with history of completely resected breast cancer with no active disease for over 3 years on long term adjuvant endocrine therapy], or investigational agent) within 4 weeks of study day 1; Please note that bisphosphonates or anti-Receptor Activator of Nuclear Factor Kappa Beta Ligand (anti-RANKL) antibody therapy is allowed if needed for management of hypercalcemia or for prevention of skeletal events.",
      "quote": "Anti-tumor therapy (chemotherapy, antibody therapy, molecular targeted therapy, retinoid therapy, hormonal therapy [except for subjects with history of completely resected breast cancer with no active disease for over 3 years on long term adjuvant endocrine therapy], or investigational agent) within 4 weeks of study day 1; Please note that bisphosphonates or anti-Receptor Activator of Nuclear Factor Kappa Beta Ligand (anti-RANKL) antibody therapy is allowed if needed for management of hypercalcemia or for prevention of skeletal events."
    },
    {
      "kind": "exclusion",
      "text": "Therapeutic or palliative radiation therapy within 2 weeks of study day 1. Subjects must have recovered from all radiotherapy related toxicity to CTCAE version 5.0 grade 1 or less with the exception of alopecia (any grade of alopecia allowed).",
      "quote": "Therapeutic or palliative radiation therapy within 2 weeks of study day 1. Subjects must have recovered from all radiotherapy related toxicity to CTCAE version 5.0 grade 1 or less with the exception of alopecia (any grade of alopecia allowed)."
    },
    {
      "kind": "exclusion",
      "text": "Other investigational procedures are excluded",
      "quote": "Other investigational procedures are excluded"
    },
    {
      "kind": "exclusion",
      "text": "Previous treatment with AMG 510 or other KRAS G12C inhibitor",
      "quote": "Previous treatment with AMG 510 or other KRAS G12C inhibitor"
    },
    {
      "kind": "exclusion",
      "text": "History of severe hypersensitivity to docetaxel or to other drugs formulated with polysorbate 80, or known sensitivity to any of the products or components to be administered during dosing.",
      "quote": "History of severe hypersensitivity to docetaxel or to other drugs formulated with polysorbate 80, or known sensitivity to any of the products or components to be administered during dosing."
    },
    {
      "kind": "exclusion",
      "text": "Use of known cytochrome P450 (CYP) 3A4 or P-gp sensitive substrates (with a narrow therapeutic window), within 14 days or 5 half-lives of the drug or its major active metabolite, whichever is longer, prior to study day 1 that was not reviewed and approved by the principal investigator and the Amgen medical monitor.",
      "quote": "Use of known cytochrome P450 (CYP) 3A4 or P-gp sensitive substrates (with a narrow therapeutic window), within 14 days or 5 half-lives of the drug or its major active metabolite, whichever is longer, prior to study day 1 that was not reviewed and approved by the principal investigator and the Amgen medical monitor."
    },
    {
      "kind": "exclusion",
      "text": "Use of strong inducers of CYP3A4 (including herbal supplements such as St. John’s wort) within 14 days or 5 half-lives (whichever is longer) prior to study day 1 that was not reviewed and approved by the principal investigator and the Amgen medical monitor.",
      "quote": "Use of strong inducers of CYP3A4 (including herbal supplements such as St. John’s wort) within 14 days or 5 half-lives (whichever is longer) prior to study day 1 that was not reviewed and approved by the principal investigator and the Amgen medical monitor."
    },
    {
      "kind": "exclusion",
      "text": "Use of warfarin. Other anticoagulation may be allowed with Amgen medical monitor approval",
      "quote": "Use of warfarin. Other anticoagulation may be allowed with Amgen medical monitor approval"
    },
    {
      "kind": "exclusion",
      "text": "Currently enrolled in another investigational device or drug study, or less than 4 weeks since ending another investigational device or drug(s), or receiving other investigational agent(s)",
      "quote": "Currently enrolled in another investigational device or drug study, or less than 4 weeks since ending another investigational device or drug(s), or receiving other investigational agent(s)"
    },
    {
      "kind": "exclusion",
      "text": "Female subject is pregnant or breastfeeding or planning to become pregnant or breastfeed during treatment and for an additional 7 days after the last dose of AMG 510 or during treatment with docetaxel and 6 months after last dose of docetaxel if planning to become pregnant.",
      "quote": "Female subject is pregnant or breastfeeding or planning to become pregnant or breastfeed during treatment and for an additional 7 days after the last dose of AMG 510 or during treatment with docetaxel and 6 months after last dose of docetaxel if planning to become pregnant."
    },
    {
      "kind": "exclusion",
      "text": "Female subjects of childbearing potential unwilling to use 1 highly effective method of contraception during treatment and for an additional 7 days after the last dose of AMG 510 and 6 months after the last dose of docetaxel.",
      "quote": "Female subjects of childbearing potential unwilling to use 1 highly effective method of contraception during treatment and for an additional 7 days after the last dose of AMG 510 and 6 months after the last dose of docetaxel."
    },
    {
      "kind": "exclusion",
      "text": "Female subjects of childbearing potential with a positive pregnancy test assessed at Screening or day 1 by a serum pregnancy test and/or urine pregnancy test.",
      "quote": "Female subjects of childbearing potential with a positive pregnancy test assessed at Screening or day 1 by a serum pregnancy test and/or urine pregnancy test."
    },
    {
      "kind": "exclusion",
      "text": "Male subjects with a female partner of childbearing potential who are unwilling to practice sexual abstinence (refrain from heterosexual intercourse) or use contraception during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product.",
      "quote": "Male subjects with a female partner of childbearing potential who are unwilling to practice sexual abstinence (refrain from heterosexual intercourse) or use contraception during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product."
    },
    {
      "kind": "exclusion",
      "text": "Male subjects with a pregnant partner who are unwilling to practice abstinence or use a condom during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product.",
      "quote": "Male subjects with a pregnant partner who are unwilling to practice abstinence or use a condom during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product."
    },
    {
      "kind": "exclusion",
      "text": "Male subjects unwilling to abstain from donating sperm during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product. Refer to Section 11.5 for additional contraceptive information.",
      "quote": "Male subjects unwilling to abstain from donating sperm during treatment and for an additional 7 days (AMG 510) or 6 months (docetaxel) after the last dose of investigational product. Refer to Section 11.5 for additional contraceptive information."
    },
    {
      "kind": "exclusion",
      "text": "Subject likely to not be available to complete all protocol-required study visits or procedures, and/or to comply with all required study procedures (eg, Clinical Outcome Assessments) to the best of the subject and investigator’s knowledge.",
      "quote": "Subject likely to not be available to complete all protocol-required study visits or procedures, and/or to comply with all required study procedures (eg, Clinical Outcome Assessments) to the best of the subject and investigator’s knowledge."
    },
    {
      "kind": "exclusion",
      "text": "History or evidence of any other clinically significant disorder, condition or disease (with the exception of those outlined above) that, in the opinion of the investigator or Amgen physician, if consulted, would pose a risk to subject safety or interfere with the study evaluation, procedures or completion, or interpretation of results.",
      "quote": "History or evidence of any other clinically significant disorder, condition or disease (with the exception of those outlined above) that, in the opinion of the investigator or Amgen physician, if consulted, would pose a risk to subject safety or interfere with the study evaluation, procedures or completion, or interpretation of results."
    }
  ]
}
